    74→// ChunkJSONL splits JSONL content at line boundaries.
    75→// This is the default chunking for agents using JSONL format (like Claude Code).
    76→func ChunkJSONL(content []byte, maxSize int) ([][]byte, error) {
    77→	lines := strings.Split(string(content), "\n")
    78→	var chunks [][]byte
    79→	var currentChunk strings.Builder
    80→
    81→	for _, line := range lines {
    82→		// Check if adding this line would exceed the chunk size
    83→		lineWithNewline := line + "\n"
    84→		if currentChunk.Len()+len(lineWithNewline) > maxSize && currentChunk.Len() > 0 {
    85→			// Save current chunk and start a new one
    86→			chunks = append(chunks, []byte(strings.TrimSuffix(currentChunk.String(), "\n")))
    87→			currentChunk.Reset()
    88→		}
    89→		currentChunk.WriteString(lineWithNewline)
    90→	}
    91→
    92→	// Add the last chunk if it has content
    93→	if currentChunk.Len() > 0 {
    94→		chunks = append(chunks, []byte(strings.TrimSuffix(currentChunk.String(), "\n")))
    95→	}
    96→
    97→	return chunks, nil
    98→}
