   100→// ReassembleJSONL concatenates JSONL chunks with newlines.
   101→func ReassembleJSONL(chunks [][]byte) []byte {
   102→	var result strings.Builder
   103→	for i, chunk := range chunks {
   104→		result.Write(chunk)
   105→		if i < len(chunks)-1 {
   106→			result.WriteString("\n")
   107→		}
   108→	}
   109→	return []byte(result.String())
   110→}
