   112→// ChunkFileName returns the filename for a chunk at the given index.
   113→// Index 0 returns the base filename, index 1+ returns with chunk suffix.
   114→func ChunkFileName(baseName string, index int) string {
   115→	if index == 0 {
   116→		return baseName
   117→	}
   118→	return baseName + fmt.Sprintf(ChunkSuffix, index)
   119→}
   120→
   121→// ParseChunkIndex extracts the chunk index from a filename.
   122→// Returns 0 for the base file (no suffix), or the chunk number for suffixed files.
   123→// Returns -1 if the filename doesn't match the expected pattern.
   124→func ParseChunkIndex(filename, baseName string) int {
   125→	if filename == baseName {
   126→		return 0
   127→	}
   128→
   129→	if !strings.HasPrefix(filename, baseName+".") {
   130→		return -1
   131→	}
   132→
   133→	suffix := strings.TrimPrefix(filename, baseName+".")
   134→	var index int
   135→	if _, err := fmt.Sscanf(suffix, "%03d", &index); err != nil {
   136→		return -1
   137→	}
   138→	return index
   139→}
   140→
   141→// SortChunkFiles sorts chunk filenames in order (base file first, then numbered chunks).
   142→func SortChunkFiles(files []string, baseName string) []string {
   143→	sorted := make([]string, len(files))
   144→	copy(sorted, files)
   145→
   146→	sort.Slice(sorted, func(i, j int) bool {
   147→		idxI := ParseChunkIndex(sorted[i], baseName)
   148→		idxJ := ParseChunkIndex(sorted[j], baseName)
   149→		return idxI < idxJ
   150→	})
   151→
   152→	return sorted
   153→}
