   160→// DetectAgentTypeFromContent detects the agent type from transcript content.
   161→// Returns "Gemini CLI" if it appears to be Gemini JSON format, empty string otherwise.
   162→// This is used when the agent type is unknown but we need to chunk/reassemble correctly.
   163→func DetectAgentTypeFromContent(content []byte) string {
   164→	// Quick check: Gemini JSON starts with { and has a messages array
   165→	trimmed := strings.TrimSpace(string(content))
   166→	if !strings.HasPrefix(trimmed, "{") {
   167→		return ""
   168→	}
   169→
   170→	// Try to parse as Gemini JSON format (object with messages array)
   171→	var transcript geminiTranscriptDetect
   172→	if err := json.Unmarshal(content, &transcript); err != nil {
   173→		return ""
   174→	}
   175→
   176→	// Must have at least one message to be considered Gemini format
   177→	if len(transcript.Messages) > 0 {
   178→		return "Gemini CLI"
   179→	}
   180→
   181→	return ""
   182→}
